const projects=[
  {name:'GIN SOAK',type:'Brand Building',idea:'Soaked in Obsession',brief:'Build a distinctive communication world for a gin brand entering a crowded, culturally fluent category.',response:'I developed the central brand thought, shaped its voice and extended the idea across film, social and retail communication.',roles:'Strategy · Creative Direction · Copy',a:'assets/cases/ginsoak/all/DPyVJRrE6aV.jpg',b:'assets/cases/ginsoak/all/DPyZ5FME5GW.jpg',more:['assets/cases/ginsoak/all/DPyaeyUk0tf.jpg','assets/cases/ginsoak/all/DPyaxeKk-mx.jpg']},
  {name:'DRACONIC',type:'Brand Building',idea:'A Voice for AI-led Trading',brief:'Give an AI trading product a clear position, recognisable tone and a social presence that could make complex finance feel relevant.',response:'I reset the positioning and tone of voice, then built the social strategy and visual direction around a sharper, more confident brand character.',roles:'Strategy · Creative Direction · Copy',a:'assets/cases/draconic/all/DVdw8fsiogc.jpg',b:'assets/cases/draconic/all/DVQnJqUCv7F.jpg',more:['assets/cases/draconic/all/DVGgjFACvMV.jpg','assets/cases/draconic/all/DU5rh2MEthR.jpg']},
  {name:'GLACIR',type:'Brand Communication',idea:'Pure Madness',brief:'Turn the positioning “Pure Madness” into a communication system with enough range to live across film and social.',response:'I led the copy direction, wrote the brand film and shaped the creative treatment and social extensions around the brand’s controlled sense of chaos.',roles:'Copy · Film · Creative Direction',a:'assets/cases/glacir/all/DPypUCME_t2.jpg',b:'assets/cases/glacir/all/DZXYjPvzkI8.jpg',more:['assets/cases/glacir/all/DYXA_GStaVJ.jpg','assets/cases/glacir/all/DPypWuKE-YL.jpg']},
  {name:'PHQ',type:'Social Identity',idea:'A Younger Brand Presence',brief:'Refresh an established brand’s social presence so it felt younger, more current and easier to recognise in motion.',response:'I created the content plan, art direction and flexible visual language, giving the brand a system that could move cleanly across formats.',roles:'Strategy · Art Direction · Design',a:'assets/phq/post-6.png',b:'assets/phq/post-5.png',more:['assets/phq/founding-01.png','assets/phq/founding-02.png'],video:'assets/phq/phq-cover.m4v'},
  {name:'META',type:'Performance Campaign',idea:'Kyunki Badhna Abhi Baaki Hai',brief:'Create performance-led communication that spoke directly to small businesses without losing Meta’s clarity or scale.',response:'I worked on creative direction, key visual design and the modular layouts that carried the campaign across different entrepreneurs and placements.',roles:'Creative Direction · Design · Layout',a:'assets/meta/meta-jaysart-01.jpg',b:'assets/meta/meta-priyassarees-clean.png',more:['assets/meta/meta-jaysart-02.jpg','assets/meta/meta-zoyapaints-clean.png']},
  {name:'ATLAS',type:'Concept Identity',idea:'Luxury Real Estate, Reframed',brief:'Develop a concept identity for a new luxury real-estate brand, from the mark to a visual language with premium range.',response:'I built the logo concept and identity system, then tested its expression across imagery, print and merchandise to establish a coherent point of view.',roles:'Identity · Art Direction · Design',a:'assets/atlas/atlas-05.png',b:'assets/atlas/atlas-07.png',more:['assets/atlas/atlas-01.png','assets/atlas/atlas-09.png']}
];
const meta=(p,i)=>`<div class="project-meta"><span>${p.type}</span><strong>${p.name}</strong><em>(${String(i+1).padStart(2,'0')})</em></div>`;
const img=(src,cls='')=>`<img class="uncropped ${cls}" loading="lazy" src="${src}" alt="">`;
document.querySelector('[data-gallery="pairs"]').innerHTML=projects.map((p,i)=>`<article class="pair-card"><div class="pair-media">${img(p.a)}${img(p.b)}</div>${meta(p,i)}</article>`).join('');
document.querySelector('[data-gallery="stack"]').innerHTML=projects.map((p,i)=>`<article class="stack-card"><div>${img(p.a)}${meta(p,i)}</div>${img(p.b,'secondary')}</article>`).join('');
document.querySelector('[data-gallery="film"]').innerHTML=projects.map((p,i)=>`<article class="film-card"><div class="frames">${img(p.a)}${img(p.b)}</div>${meta(p,i)}</article>`).join('');
document.querySelector('[data-gallery="archive"]').innerHTML=projects.map((p,i)=>`<article class="archive-card"><b>${String(i+1).padStart(2,'0')}</b><h3>${p.name}</h3><span>${p.type}</span><em>VIEW ↗</em><div class="archive-preview">${img(p.a)}${img(p.b)}</div></article>`).join('');
document.querySelector('[data-gallery="contact"]').innerHTML=projects.map((p,i)=>`<article class="contact-card">${img(p.a)}${meta(p,i)}</article>`).join('');
document.querySelector('[data-gallery="chapters"]').innerHTML=projects.map((p,i)=>`<article class="chapter">${img(p.a,'lead')}${img(p.b,'support')}${meta(p,i)}</article>`).join('');
const story=(p)=>`<div class="story"><p class="eyebrow">${p.type}</p><h3>${p.idea}</h3><dl><div><dt>The brief</dt><dd>${p.brief}</dd></div><div><dt>The response</dt><dd>${p.response}</dd></div></dl><strong>${p.roles}</strong></div>`;
const fullMedia=(p,withVideo=false)=>`${img(p.a)}${withVideo&&p.video?`<video class="uncropped-video" controls muted playsinline preload="metadata"><source src="${p.video}"></video>`:img(p.b)}${p.more.map(x=>img(x)).join('')}`;
document.querySelector('[data-gallery="elias-index"]').innerHTML=projects.map((p,i)=>`<article class="elias-card"><div class="elias-copy"><span>${String(i+1).padStart(2,'0')} / 06</span><h3>${p.name}</h3><p>${p.idea}</p><b>${p.roles}</b></div><div class="elias-frame">${img(p.a)}</div></article>`).join('');
document.querySelector('[data-gallery="case-narrative"]').innerHTML=projects.map((p,i)=>`<article class="narrative-case"><div class="case-number">CASE ${String(i+1).padStart(2,'0')}</div>${story(p)}<div class="narrative-gallery">${img(p.a)}${img(p.b)}${img(p.more[0])}</div></article>`).join('');
document.querySelector('[data-gallery="editorial-journal"]').innerHTML=projects.map((p,i)=>`<article class="journal-case"><div class="journal-meta"><span>Case ${String(i+1).padStart(2,'0')}</span><span>${p.type}</span><span>${p.roles}</span></div><h3>${p.name}:<br><i>${p.idea}</i></h3><p class="journal-deck">${p.response}</p><div class="journal-media">${img(p.a)}${img(p.b)}</div><div class="journal-notes"><p><b>Context</b>${p.brief}</p><p><b>Contribution</b>${p.response}</p></div></article>`).join('');
document.querySelector('[data-gallery="sticky-chapters"]').innerHTML=projects.map((p,i)=>`<article class="sticky-case"><div class="sticky-copy"><span>${String(i+1).padStart(2,'0')}</span><h3>${p.name}</h3><p>${p.idea}</p><strong>${p.roles}</strong><small>${p.response}</small></div><div class="asset-stream">${fullMedia(p,true)}</div></article>`).join('');
document.querySelector('[data-gallery="case-library"]').innerHTML=projects.map((p,i)=>`<article class="library-case"><div class="library-head"><span>${String(i+1).padStart(2,'0')}</span><h3>${p.name}</h3><p>${p.idea}</p></div><div class="library-story">${story(p)}</div><div class="library-grid">${fullMedia(p,true)}</div></article>`).join('');
document.querySelector('[data-gallery="taylor-index"]').innerHTML=projects.map((p,i)=>`<article class="taylor-row"><span>${String(i+1).padStart(2,'0')}</span><h3>${p.name}</h3><p>${p.type}</p><div class="taylor-reveal">${img(p.a)}</div></article>`).join('');
document.querySelector('[data-gallery="cover-flow"]').innerHTML=projects.map((p,i)=>`<article class="cover-case"><div class="cover-stage">${img(p.a)}</div><div class="cover-credit"><span>${String(i+1).padStart(2,'0')} / 06</span><h3>${p.name}</h3><p>${p.idea}</p><b>${p.roles}</b></div></article>`).join('');
document.querySelector('[data-gallery="domino-edit"]').innerHTML=projects.map((p,i)=>`<article class="domino-card">${img(p.a)}<span>${String(i+1).padStart(2,'0')} · ${p.name}</span><strong>${p.idea}</strong></article>`).join('');
document.querySelector('[data-gallery="split-archive"]').innerHTML=`<div class="split-list">${projects.map((p,i)=>`<button type="button" data-split="${i}" class="${i===0?'active':''}"><span>${String(i+1).padStart(2,'0')}</span><strong>${p.name}</strong><em>${p.type}</em></button>`).join('')}</div><div class="split-stage">${img(projects[0].a)}<h3>${projects[0].idea}</h3><p>${projects[0].roles}</p></div>`;
document.querySelectorAll('[data-split]').forEach(button=>button.addEventListener('mouseenter',()=>{const p=projects[Number(button.dataset.split)];document.querySelectorAll('[data-split]').forEach(x=>x.classList.remove('active'));button.classList.add('active');const stage=document.querySelector('.split-stage');stage.innerHTML=`${img(p.a)}<h3>${p.idea}</h3><p>${p.roles}</p>`}));
document.querySelector('[data-gallery="motion-ledger"]').innerHTML=projects.map((p,i)=>`<article class="ledger-case"><div class="ledger-credit"><span>${String(i+1).padStart(2,'0')}</span><h3>${p.name}</h3><p>${p.response}</p></div><div class="ledger-strip">${fullMedia(p,true)}</div></article>`).join('');
const activate=(id,smooth=true)=>{const target=document.querySelector(`#${id}`);const button=document.querySelector(`[data-target="${id}"]`);if(!target||!button)return;document.querySelectorAll('aside button,.option').forEach(el=>el.classList.remove('active'));button.classList.add('active');target.classList.add('active');history.replaceState(null,'',`#${id}`);window.scrollTo({top:target.offsetTop-58,behavior:smooth?'smooth':'auto'})};
document.querySelectorAll('aside button').forEach(button=>button.addEventListener('click',()=>activate(button.dataset.target)));
if(location.hash)activate(location.hash.slice(1),false);
